from sklearn.linear_model import LinearRegression

def log_features(X, y):
    return pd.DataFrame({
        "log_sqft": np.log(X["sqft"]),
        "log_per_sqft": np.log(y / X["sqft"]),
    })

leaky = LinearRegression().fit(log_features(X_train, y_train), np.log(y_train))
